insert into posts (board,title_ko,content_ko,excerpt_ko,thumbnail_url,images,author,is_pinned,created_at) values
('award','손기헌 교수 연구실, 유체기계학회에서 ''우수발표상'' 수상','<p>산업/차량용 모터의 방열 특성은 에너지 효율과 성능에 직접적인 영향을 미친다.</p><p>본 연구는 회전좌표계 기반의 열유동 해석과 이를 통한 열 회로 특성 분석/평가를 통해 차세대 고효율 동기 전동기 개발에 기여하였다.</p><p>팬 블레이드, 회전수, 열교환 fin의 최적 설계를 수행하여 전동기 고효율화/고성능화를 달성하였으며, 이를 인정받아 유체기계학회 ''우수발표상''을 수상하였다.</p>','산업/차량용 모터의 방열 특성은 에너지 효율과 성능에 직접적인 영향을 미친다. 본 연구는 회전좌표계 기반의 열유동 해석과 이를 통한 열 회로 특성 분석/평가를 통해 차세대 고효율 동기 전동기 개발에 기여하였다. 팬 블레이드, 회전수, 열교환 fin의 최적 설계를 수행하여 전동기 고효율화/고성능화를 달성하','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_OXbBUKfz_1778247655333.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_OXbBUKfz_1778247655333.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-05-13'),('research','송지환 교수 연구팀, 분석 화학 분야 국제 저명 저널 ''Analytical Chemistry'' 논문 게재','<p>송지환 교수와 한국표준과학연구원(KRISS) 공동연구팀이 유세포분석기에서 발생하는 입자 농도 측정의 크기 의존적 편향을 규명한 연구를 미국화학회(ACS) 저널 Analytical Chemistry에 발표하였다.</p><p>논문 제목은 "Comparative Analysis of Sample Loop and Counting Bead–Based Methods for Size-Dependent Bias in Flow Cytometry"로, 연구팀은 다중물리 시뮬레이션을 통해 전통적인 카운팅 비드 방식에서 관찰되는 농도 편향이 샘플 튜브 내부의 미세 유체역학적 차이에서 비롯됨을 정량적으로 밝혔다.</p><p>연구 결과, 입자 크기에 따라 중력·부력·항력·브라운운동의 상대적 영향이 달라지고, 이 차이가 큰 비드의 과대표집·작은 비드의 과소표집으로 이어지는 구조적 편향을 유발함이 확인되었다. 연구팀은 편향을 최소화하는 대안으로 정량 주입 기반(sample loop) 측정법이 효과적임을 제시하였다.</p><p>이번 연구는 입자·세포·나노물질의 정확한 농도 측정 체계 구축을 위한 이론적 기반을 제공하며, 향후 유세포분석기의 정량성과 표준화에 중요한 기여를 할 것으로 기대된다.</p>','송지환 교수와 한국표준과학연구원(KRISS) 공동연구팀이 유세포분석기에서 발생하는 입자 농도 측정의 크기 의존적 편향을 규명한 연구를 미국화학회(ACS) 저널 Analytical Chemistry에 발표하였다. 논문 제목은 "Comparative Analysis of Sample Loop and Coun','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_oRjCIcQs_EC86A1ECA780ED9998_1.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_oRjCIcQs_EC86A1ECA780ED9998_1.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-05-13'),('research','송지환 교수 연구팀, 국제 권위지 ''Nature Communications'' 논문 게재','<p>송지환 교수와 건국대학교, Harvard Medical School, 서울대학교 분당병원 공동연구팀이 혈액 속 췌장암 표지자를 15분 만에 정밀 분석할 수 있는 차세대 신속진단 기술을 개발했다. 이번 성과는 세계적 권위의 학술지 〈네이처 커뮤니케이션즈(Nature Communications)〉에 게재되며 기술적 완성도와 학술적 가치를 동시에 입증받았다.</p><p>췌장암은 ''침묵의 살인자''로 불릴 만큼 초기 증상이 미미해 발견 시 생존율이 극히 낮은 난치성 질환이다. 기존의 영상 의학적 진단이나 침습적 방식은 환자의 신체적·경제적 부담이 컸고, 일반적인 혈액 검사는 민감도 측면에서 조기 발견 도구로 활용되기에 한계가 명확했다.</p><p>연구팀은 신호 증폭형 측방유동면역분석법인 ''SELFI(Signal-Enhanced Lateral Flow Immunoassay)'' 검사법을 새롭게 개발했다. SELFI는 금 나노입자를 실리카 나노입자 표면에 고도로 조립한 나노구조체를 활용해 ''핫스폿'' 효과를 극대화함으로써 기존 신속진단키트 대비 검출 민감도를 약 28배 향상시켰다. 이를 통해 췌장암 표지자 ''CA19-9''를 0.15 U/mL 수준까지 검출할 수 있으며 분석 시간은 15분에 불과하다.</p>','송지환 교수와 건국대학교, Harvard Medical School, 서울대학교 분당병원 공동연구팀이 혈액 속 췌장암 표지자를 15분 만에 정밀 분석할 수 있는 차세대 신속진단 기술을 개발했다. 이번 성과는 세계적 권위의 학술지 〈네이처 커뮤니케이션즈(Nature Communications)〉에 게재되며','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_Ra4T8y7E_EC86A1ECA780ED9998_2.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_Ra4T8y7E_EC86A1ECA780ED9998_2.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-05-13'),('research','손기헌 교수, 열공학 분야 상위 4.7% 저널 "Applied Thermal Engineering"에 논문 게재','<p>손기헌 교수 연구실(1저자 박재성 박사과정)의 연구성과가 ''Applied Thermal Engineering''에 게재되었다. 이 저널은 Elsevier에서 발간하는 JCR 상위 4.7%의 SCIE 저널로, 열공학/열전달에 관한 연구주제를 다룬다.</p><p>수전해는 전기화학 반응으로 발생한 수소 기포를 포집하는 가장 신뢰성 있는 수소 생산 공법이다. 발생 기포는 에너지 캐리어이자 절연체로 수전해 효율에 중요한 영향을 미치며, 보다 실질적인 수전해 성능의 정량 평가를 위해서는 풀 비등(pool boiling)과 마찬가지로 연속적인 기포 핵생성-성장-이탈 거동의 고려가 요구된다.</p><p>본 논문에서는 상변화 열전달 및 수소 가스 확산을 동시에 고려한 수치모델을 개발하고, 주기적 기포 성장-이탈 거동을 포함하는 cyclic computation 수치모델을 최초로 확장 개발하였다.</p><p>- 논문 제목: Cyclic computation of bubble growth in water electrolysis using a level-set approach<br>- 논문 저자: 박재성, 손기헌(지도교수)</p>','손기헌 교수 연구실(1저자 박재성 박사과정)의 연구성과가 ''Applied Thermal Engineering''에 게재되었다. 이 저널은 Elsevier에서 발간하는 JCR 상위 4.7%의 SCIE 저널로, 열공학/열전달에 관한 연구주제를 다룬다. 수전해는 전기화학 반응으로 발생한 수소 기포를 포집하는 가','https://me.sogang.ac.kr/v2/data/file/sub6_1/thumb-2750398411_EflIK5eJ_ED998DEBB3B41_900x346.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/thumb-2750398411_EflIK5eJ_ED998DEBB3B41_900x346.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-05-29'),('award','임우석 학부생, 2025년도 추계 소음진동 학술대회 학생부문 우수논문상 수상','<p>임우석 학부생이 이승엽 교수 지도하에 URECA 인턴과 연구프로젝트 과목에서 연구한 논문이 2025년 한국소음진동공학회 추계학술대회에서 많은 대학원생들을 제치고 우수논문상을 수상했다.</p><p>최근 각광받고 있는 영강성 메타구조를 엠보싱 형태로 설계하고 실험적으로 검증한 연구로, 다양한 진동저감 분야에 적용될 수 있다.</p><p>- 제목: 엠보싱 돔-벽 격자 메타구조의 준영강성 디자인<br>- 저자: 임우석, 심명석, 임홍석, 이승엽<br>- 주관: 한국소음진동공학회</p>','임우석 학부생이 이승엽 교수 지도하에 URECA 인턴과 연구프로젝트 과목에서 연구한 논문이 2025년 한국소음진동공학회 추계학술대회에서 많은 대학원생들을 제치고 우수논문상을 수상했다. 최근 각광받고 있는 영강성 메타구조를 엠보싱 형태로 설계하고 실험적으로 검증한 연구로, 다양한 진동저감 분야에 적용될 수','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_P3KSLNlu_2025EB8584_ECB694EAB384_EC868CEC9D8CECA784EB8F99_ED9599EC88A0EB8C80ED9A8C_EC9AB0EC8898EB85BCEBACB8EC8381ED9599EC839DEBB680EBACB8_EC9E84EC9AB0EC849DEC849CEAB095EB8C80ED9599EAB590.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_P3KSLNlu_2025EB8584_ECB694EAB384_EC868CEC9D8CECA784EB8F99_ED9599EC88A0EB8C80ED9A8C_EC9AB0EC8898EB85BCEBACB8EC8381ED9599EC839DEBB680EBACB8_EC9E84EC9AB0EC849DEC849CEAB095EB8C80ED9599EAB590.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-06-05'),('research','손기헌 교수, Applied Mathematics 분야 최고 수준 저널 ''Mathematics and Computers in Simulation''에 논문 게재','<p>손기헌 교수 연구실(1저자: 박재성 박사과정)의 연구 성과가 Applied Mathematics 분야 상위 1.0% 저널인 ''Mathematics and Computers in Simulation''에 게재되었다.</p><p>다상유동 계면 추적 기법 중 VOF 방법은 체적 보존적 특성의 이점으로 다양한 응용분야에서 빈번히 활용된다. 하지만 초음파 캐비테이션 기포 계산에 있어 VOF 방법은 알고리즘 특성상 질량 보존적 한계와 계면의 기하학적 특성 계산의 한계가 존재한다.</p><p>본 연구에서는 이러한 한계 극복을 위한 CLSVOF(coupled level-set and volume-of-fluid) 방법을 개발하였고, 다양한 다상유동 문제들을 통해 검증하였다. 초음파 조건에서의 기포-기포 및 기포-cell 간 상호작용을 계산하였고, 이의 타당성을 수치적으로 분석하였다.</p><p>- 논문 제목: A CLSVOF method for simulating bubble motion in ultrasonic fields near a deformable solid cell<br>- 논문 저자: 박재성, 손기헌(지도교수)</p>','손기헌 교수 연구실(1저자: 박재성 박사과정)의 연구 성과가 Applied Mathematics 분야 상위 1.0% 저널인 ''Mathematics and Computers in Simulation''에 게재되었다. 다상유동 계면 추적 기법 중 VOF 방법은 체적 보존적 특성의 이점으로 다양한 응용분야에서 ','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_67AhXoER_EC8BA4ECA081.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_67AhXoER_EC8BA4ECA081.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-06-30'),('award','이준희 대학원생, 2025년 대한기계학회 본부학술대회 우수논문상 수상','<p>이준희 석사과정 대학원생(지도교수 강성원)이 2025년 대한기계학회 본부학술대회에서 우수논문상을 수상하였다.</p><p>이준희 대학원생은 수소자동차 공기 정화를 위한 활성탄 입자 및 적층 형상을 고려한 활성탄 필터 유동 해석 연구를 수행하고 발표하여 우수논문상을 수상했다.</p><p>- 제목: 활성탄 입자 및 적층 형상을 고려한 활성탄 필터 유동 해석<br>- 저자: 이준희, 강성원<br>- 주관: 대한기계학회</p>','이준희 석사과정 대학원생(지도교수 강성원)이 2025년 대한기계학회 본부학술대회에서 우수논문상을 수상하였다. 이준희 대학원생은 수소자동차 공기 정화를 위한 활성탄 입자 및 적층 형상을 고려한 활성탄 필터 유동 해석 연구를 수행하고 발표하여 우수논문상을 수상했다. - 제목: 활성탄 입자 및 적층 형상을 고','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_XHIsFDnB_EC9DB4ECA480ED9DAC_EC8898EC8381.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_XHIsFDnB_EC9DB4ECA480ED9DAC_EC8898EC8381.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-07-11'),('research','신충수 교수, 2026년 과학기술정보통신부 기초연구실 지원사업 선정','<p>우리 학과 신충수 교수(연구책임자), 김남근 교수, 송지환 교수와 강원대학교 기계융합공학부 이형석 교수로 구성된 공동연구팀이 과학기술정보통신부와 한국연구재단이 주관하는 2026년도 심화형 기초연구실 지원사업에 신규 선정되었다.</p><p>연구과제명은 ''3D TENG 인솔 임베디드 피지컬 AI 엑소부츠 기반 보행능력 증강 기초연구실''이며, 연구기간은 2026년 7월부터 2029년 6월까지 3년간 총 15억원의 연구비를 지원받는다.</p><p>최근 보행 및 작업을 보조하는 엑소스켈레톤·엑소수트에 대한 수요가 증가하고 있으나, 현재 기술은 실제 환경에서 활용되기에는 여전히 여러 한계를 지니고 있다. 해당 과제는 외부 구동케이블을 최소화한 간결한 모듈형 엑소부츠 개발을 목표로 하며, 자가전원 방식의 TENG 센서 인솔을 개발하여 보행 센싱 모듈을 구현하고, 실시간 진단과 적응이 가능한 지능형 AI 제어 알고리즘을 개발해 엑소부츠를 제어할 계획이다. 또한 인간 대상 실험을 통해 엑소부츠의 보행능력 증강 효과를 실증할 예정이다.</p>','우리 학과 신충수 교수(연구책임자), 김남근 교수, 송지환 교수와 강원대학교 기계융합공학부 이형석 교수로 구성된 공동연구팀이 과학기술정보통신부와 한국연구재단이 주관하는 2026년도 심화형 기초연구실 지원사업에 신규 선정되었다. 연구과제명은 ''3D TENG 인솔 임베디드 피지컬 AI 엑소부츠 기반 보행능력','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_MDlvteQk_EC8BA0ECB6A9EC8898_EAB8B0ECB488EC97B0EAB5ACEC8BA4.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_MDlvteQk_EC8BA0ECB6A9EC8898_EAB8B0ECB488EC97B0EAB5ACEC8BA4.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-07-14'),('research','이승엽 교수, 저명 저널 Green Chemistry 표지 논문 게재','<p>이승엽 교수 연구실에서 화학과 연구팀과 공동 연구한 논문이 그린 에너지 분야 저명 저널인 Green Chemistry (IF 10.6)의 2026.6.15자 표지논문으로 게재되었다.</p><p>본 논문은 기계공학과 서한복 박사와 화학과 박희선 박사가 공동 제1저자로, 이승엽 교수와 화학과 허남회 교수가 공동 교신저자로 참여하였다. 기계공학과의 고농도 수소 나노버블 기술과 화학과의 루테늄 촉매 기술을 함께 사용하여 폐질산에서 수소 이동체로 각광받는 암모니아를 저온 저압에서 발생시키는 획기적인 연구이다.</p><p>암모니아 생산은 하버-보슈 방법을 이용해 현재까지도 고온(400~500°C), 고압(200기압 이상) 조건에서 이루어지는데, 본 연구는 나노버블과 촉매를 이용하여 저온(60°C), 저압(10기압 이하) 조건에서 폐질산으로부터 암모니아 생산이 가능함을 보인 원천 연구 성과로서, 향후 사업화 연구를 통해 수소 전환 시대에 큰 파급효과가 있을 것으로 예상된다. 본 연구는 연구재단 파이오니아 도전형 과제 지원으로 수행되었다.</p><p>▶ 제목: Ultrasound-assisted catalytic valorization of nitric acid waste to ammonia using hydrogen nanobubbles<br>▶ 저자: 박희선, 서한복, 임흥빈, 이승엽, 허남회<br>▶ 논문 링크: <a href="https://doi.org/10.1039/d6gc00304d" target="_blank">https://doi.org/10.1039/d6gc00304d</a></p>','이승엽 교수 연구실에서 화학과 연구팀과 공동 연구한 논문이 그린 에너지 분야 저명 저널인 Green Chemistry (IF 10.6)의 2026.6.15자 표지논문으로 게재되었다. 본 논문은 기계공학과 서한복 박사와 화학과 박희선 박사가 공동 제1저자로, 이승엽 교수와 화학과 허남회 교수가 공동 교신저','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_A0KXxBa3_2026GreenChemistry_CoverPage.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_A0KXxBa3_2026GreenChemistry_CoverPage.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-07-16'),('award','강형우 대학원생, 2026년 대통령과학장학생 선정','<p>강형우 석사과정 대학원생(지도교수 김상엽)이 2026년 대통령과학장학생으로 선정되었다.</p><p>한국장학재단과 과학기술정보통신부는 이공계 최우수 인재들이 세계 최고 수준의 연구인력으로 성장할 수 있도록 지원하기 위해 2026년 대통령과학장학금 신규장학생으로 학부생 157명, 대학원생 120명 등 총 277명을 선발했다. 올해 대학원 선발 경쟁률은 약 22대 1이었다.</p><p>최종 선발된 대학원 대통령과학장학생에게는 대통령 명의의 장학증서를 수여하고, 석사과정생에게는 매월 150만 원, 박사과정생에게는 매월 200만 원의 장학금을 지원한다.</p><p>강형우 석사과정생은 "본교에서 쌓아온 연구의 가치를 인정받은 것 같아 기쁘다"며 "앞으로도 대한민국 항공우주 소재기술 발전에 기여하는 연구자로서 성장하겠다"고 소감을 밝혔다.</p>','강형우 석사과정 대학원생(지도교수 김상엽)이 2026년 대통령과학장학생으로 선정되었다. 한국장학재단과 과학기술정보통신부는 이공계 최우수 인재들이 세계 최고 수준의 연구인력으로 성장할 수 있도록 지원하기 위해 2026년 대통령과학장학금 신규장학생으로 학부생 157명, 대학원생 120명 등 총 277명을 선','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_Wwa96MH7_EAB095ED9895EC9AB0.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_Wwa96MH7_EAB095ED9895EC9AB0.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-07-29'),('award','김도영 대학원생, ''제8회 미래형자동차 핵심기술 R&D 전문인력양성사업 성과발표회'' 우수상 수상','<p>김도영 석사과정 대학원생(지도교수: 정석환)이 ''제8회 미래형자동차 핵심기술 R&amp;D 전문인력양성사업 산학 프로젝트 성과발표회''에서 우수상을 수상하였다.</p><p>김도영 대학원생은 ''Reinforcement Learning Framework for Precise Grasping of Deformable Objects via Direct-Drive Motor-Based Articulated Gripper without any External Sensors''를 주제로 직접구동 모터 기반 다관절 그리퍼의 강화학습 기반 변형체 센서리스 비파손 파지 연구에 대해 성과 발표를 진행하였다.</p><p>본교를 포함한 연세대학교, 고려대학교, GIST, 인천대학교 총 5개 대학 17팀이 참가하였으며, 김도영 대학원생은 구두 발표에서 99.4/100점으로 전체 1위 및 차량SW 트랙 부문 우수상을 수상하였다.</p>','김도영 석사과정 대학원생(지도교수: 정석환)이 ''제8회 미래형자동차 핵심기술 R&D 전문인력양성사업 산학 프로젝트 성과발표회''에서 우수상을 수상하였다. 김도영 대학원생은 ''Reinforcement Learning Framework for Precise Grasping of Deformable Object','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_e58GOPQj_EC9E85EC8381EAB8B0EC82ACEC82ACECA784_EAB980EB8F84EC9881.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_e58GOPQj_EC9E85EC8381EAB8B0EC82ACEC82ACECA784_EAB980EB8F84EC9881.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-07-29'),('award','박규빈 대학원생, JCK MEMS/NEMS 2026 우수 구두발표상 수상','<p>박규빈 석박통합과정(지도교수: 박정열 교수) 대학원생이 지난 7월 8일부터 10일까지 부산 벡스코(BEXCO)에서 개최된 한·중·일 MEMS/NEMS 공동학술대회(JCK MEMS/NEMS 2026)에서 우수 구두발표상(Best Oral Presentation Award)을 수상하였다.</p><p>박규빈 대학원생은 "A Multimodal Ionic Transistor Enabled by Wavelength-Specific Plasmonic Base Modulation"을 주제로 연구 결과를 발표하였다.</p><p>본 연구에서는 금·은 나노 입자로 구성된 플라즈모닉 베이스가 조사 파장에 따라 서로 다른 광학적 반응을 나타내는 특성을 활용하여 나노채널 내부의 이온 수송 및 전류 증폭 거동을 광학적·전기적으로 제어할 수 있는 다중모드 이온 트랜지스터를 제안하였다.</p>','박규빈 석박통합과정(지도교수: 박정열 교수) 대학원생이 지난 7월 8일부터 10일까지 부산 벡스코(BEXCO)에서 개최된 한·중·일 MEMS/NEMS 공동학술대회(JCK MEMS/NEMS 2026)에서 우수 구두발표상(Best Oral Presentation Award)을 수상하였다. 박규빈 대학원생은 ','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_81jvIthz_EBB095EAB79CEBB988.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_81jvIthz_EBB095EAB79CEBB988.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-08-03'),('research','손기헌 교수, 열/물질전달 저명 저널 "International Communications in Heat and Mass Transfer"에 논문 게재','<p>손기헌 교수 연구실에서 수행한 연구가 열 및 물질전달 분야 국제 학술지인 International Communications in Heat and Mass Transfer에 게재되었다. 해당 저널은 JCR 기준 상위 7.8%에 해당하는 SCIE급 국제저명 저널이다. 이번 연구는 김민준 석사과정생이 제1저자로 참여하였다.</p><p>흡착식 제습 및 건조 시스템에서 흡착제 재생(desiccant bed regeneration)은 흡착제의 반복적 사용을 가능하게 하며, 전체 시스템의 에너지 효율을 결정하는 핵심 과정이다. 특히 zeolite는 우수한 수분 흡착 성능으로 산업용 제습 및 가스 정제 공정에 널리 사용되지만, 흡착된 수분을 제거하는 열재생(thermal regeneration) 과정에서는 열전달, 물질전달, 흡착 평형, 탈착 속도가 복합적으로 작용하여 정확한 예측이 어렵다.</p><p>본 연구에서는 2차원 축대칭 모델을 구축하여 zeolite 흡착제 충전층의 흡착 및 열재생 과정을 해석하였다. 개발된 모델은 실험 결과와 비교하여 검증되었으며, 기존 1차원 모델이 재생 시간을 실제보다 짧게 예측한다는 점을 정량적으로 확인하였다.</p>','손기헌 교수 연구실에서 수행한 연구가 열 및 물질전달 분야 국제 학술지인 International Communications in Heat and Mass Transfer에 게재되었다. 해당 저널은 JCR 기준 상위 7.8%에 해당하는 SCIE급 국제저명 저널이다. 이번 연구는 김민준 석사과정생이 제1저','https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_VUfiqpy6_EAB980EBAFBCECA480.jpg','[{"url": "https://me.sogang.ac.kr/v2/data/file/sub6_1/2750398411_VUfiqpy6_EAB980EBAFBCECA480.jpg", "caption": ""}]'::jsonb,'최고관리자',false,'2026-08-14'),('notice','현대모비스 연구소 초청행사','<p>현대모비스 연구소 초청행사가 아래와 같이 개최됩니다.</p><h3>1. 일시 및 장소</h3><p>9/11(금), 현대모비스 마북연구소 (경기도 용인시 기흥구 마북로240번길 17-2)</p><h3>2. 상세 일정</h3><ul><li>~10:00 버스 이용 학교→연구소 이동</li><li>10:00~12:00 회사 소개, 장학제도 설명회, 테크 투어</li><li>12:00~14:00 중식 교류회</li><li>14:00~ 버스 이용 학교 복귀</li></ul><h3>3. 모집 인원</h3><p>20명 — 컴퓨터공학과, 인공지능학과, 전자공학과, 기계공학과 3~4학년 휴/재학생</p><h3>4. 접수</h3><p>링크: https://forms.gle/a3Nj2x5waLUNokRM7 (마감 8월 24일(월))<br>문의: 공과대학행정팀(R514), 02-705-8462</p>','현대모비스 연구소 초청행사가 아래와 같이 개최됩니다. 1. 일시 및 장소 9/11(금), 현대모비스 마북연구소 (경기도 용인시 기흥구 마북로240번길 17-2) 2. 상세 일정 ~10:00 버스 이용 학교→연구소 이동 10:00~12:00 회사 소개, 장학제도 설명회, 테크 투어 12:00~14:00 중',NULL,'[]'::jsonb,'최고관리자',false,'2026-08-14'),('notice','자유전공학부 기계공학 소개 자료','<p>자유전공학부 학생의 전공 탐색을 돕기 위한 기계공학 소개자료입니다.<br>기계공학의 교육 내용과 진로, 주요 분야를 확인해 보시기 바랍니다.</p>','자유전공학부 학생의 전공 탐색을 돕기 위한 기계공학 소개자료입니다. 기계공학의 교육 내용과 진로, 주요 분야를 확인해 보시기 바랍니다.',NULL,'[]'::jsonb,'최고관리자',false,'2026-08-19'),('notice','대한기계학회 기계공학 소개 자료','<p>대한기계학회에서 발간한 기계공학 소개자료를 통해 기계공학의 다양한 분야와 진로를 살펴보시기 바랍니다.</p><p>예비 공학도 여러분의 많은 관심과 활용 바랍니다.</p>','대한기계학회에서 발간한 기계공학 소개자료를 통해 기계공학의 다양한 분야와 진로를 살펴보시기 바랍니다. 예비 공학도 여러분의 많은 관심과 활용 바랍니다.',NULL,'[]'::jsonb,'최고관리자',false,'2026-08-19'),('notice','2026년 하반기 서강대-삼성전자DS 반도체Track프로그램 산학장학생 지원 공지','<h3>1. 삼성반도체트랙프로그램 개요</h3><p>삼성전자 Device Solutions(DS) 부문의 반도체 전문 기술인력 양성을 목적으로 협약 기간 동안 반도체 분야(설계, 공정 및 소자, 소프트웨어)에서 우수 인력 확보 (2027년 1학기부터는 석사만 선발하는 석사 트랙으로 전환 예정). 선발된 장학생은 삼성전자 DS 부문에 입사하며, 상위 학위 연계 진학 시 삼성전자 연구원이 공동지도 가능.</p><h3>2. 지원대상 및 자격요건</h3><p>전자공학과, 반도체공학과, 컴퓨터공학과, 화공생명공학과, 기계공학과, 물리학과, 화학과 제1전공 학부 6학기 이상 재학생, 석사 1학기 이상 재학생(휴학생은 복학 후 지원 가능).</p><p>자세한 내용은 https://ee.sogang.ac.kr/kor/research/program.php 를 참고하세요.</p>','1. 삼성반도체트랙프로그램 개요 삼성전자 Device Solutions(DS) 부문의 반도체 전문 기술인력 양성을 목적으로 협약 기간 동안 반도체 분야(설계, 공정 및 소자, 소프트웨어)에서 우수 인력 확보 (2027년 1학기부터는 석사만 선발하는 석사 트랙으로 전환 예정). 선발된 장학생은 삼성전자 D',NULL,'[]'::jsonb,'최고관리자',false,'2026-08-20'),('notice','2026년 하반기 서강대-삼성전자DS 반도체Track프로그램 온라인/오프라인 설명회','<h3>온라인(Zoom) 설명회</h3><ul><li>일시: 2026년 8월 28일(금) 오후 5시</li><li>대상: [학사·석사] 전자공학과/반도체공학과/컴퓨터공학과/화공생명공학과/기계공학과/물리학과/화학과</li><li>URL: https://sogang-ac-kr.zoom.us/j/88068908132</li></ul><h3>오프라인(교내) 트랙 상담 부스</h3><ul><li>운영일시: 2026년 9월 2일(수) — 세부사항 추후 공지</li></ul><h3>2026년 하반기 삼성반도체Track프로그램 지원서 제출일정</h3><ul><li>지원일정: 2026년 8월 24일(월) ~ 9월 2일(수) 오후 1시까지</li><li>제출방법: 지원서 및 구비서류를 PDF로 변환하여 트랙 공식메일 sses@sogang.ac.kr 로 제출</li><li>매뉴얼 및 양식: https://ee.sogang.ac.kr/kor/research/program.php</li></ul><p>※ 지원서 작성 전 작성 매뉴얼을 반드시 확인하시기 바랍니다.</p>','온라인(Zoom) 설명회 일시: 2026년 8월 28일(금) 오후 5시 대상: [학사·석사] 전자공학과/반도체공학과/컴퓨터공학과/화공생명공학과/기계공학과/물리학과/화학과 URL: https://sogang-ac-kr.zoom.us/j/88068908132 오프라인(교내) 트랙 상담 부스 운영일시: 202',NULL,'[]'::jsonb,'최고관리자',false,'2026-08-20'),('notice','기계공학과 인지컨트롤스 장학금 대상자 선발안내','<p>인지컨트롤스 장학금 대상자 선발 결과를 안내드립니다. 선발된 학생은 학과사무실(R618)로 문의 바랍니다.</p>','인지컨트롤스 장학금 대상자 선발 결과를 안내드립니다. 선발된 학생은 학과사무실(R618